xml.Script:
        if not VarExists('Colors[0]') then begin
            clYellow       := 'FFFF00';
            clLightBlue    := '2828FF';
            clBlue         := '0000A0';
            clBrown        := '800000';
            clLightViolett := 'FF0080';
            clRed          := 'FF0000';
            clLightGreen   := '00FF00';
            clGreen        := '008000';
            clViolett      := '800080';
            clCyan         := '00DCB4';

            Colors[ 0] := clLightViolett;
            Colors[ 1] := clBlue;
            Colors[ 2] := clYellow;
            Colors[ 3] := clRed;
            Colors[ 4] := clBrown;
            Colors[ 5] := clLightBlue;
            Colors[ 6] := clLightGreen;
            Colors[ 7] := clGreen;
            Colors[ 8] := clCyan;
            Colors[ 9] := clViolett;
            Colors[10] := Colors[ 0];
            Colors[11] := Colors[ 1];
            Colors[12] := Colors[ 2];
            Colors[13] := Colors[ 3];
            Colors[14] := Colors[ 4];
            Colors[15] := Colors[ 5];
            Colors[16] := Colors[ 6];
            Colors[17] := Colors[ 7];
            Colors[18] := Colors[ 8];
            Colors[19] := Colors[ 9];
        end;

        if not VarExists('R') then
            R := 0.7;

        phi := (Sqrt(5) - 1) / 2; // The golden ratio
        a := R / sqrt(phi + 3);
        b := a / phi;

        // Vertices (corners)

        Vx[ 0] := 0; Vy[ 0] := a; Vz[ 0] := b;
        Vx[ 1] := 0; Vy[ 1] := a; Vz[ 1] :=-b;
        Vx[ 2] := 0; Vy[ 2] :=-a; Vz[ 2] :=-b;
        Vx[ 3] := 0; Vy[ 3] :=-a; Vz[ 3] := b;
        Vx[ 4] := b; Vy[ 4] := 0; Vz[ 4] := a;
        Vx[ 5] :=-b; Vy[ 5] := 0; Vz[ 5] := a;
        Vx[ 6] :=-b; Vy[ 6] := 0; Vz[ 6] :=-a;
        Vx[ 7] := b; Vy[ 7] := 0; Vz[ 7] :=-a;
        Vx[ 8] := a; Vy[ 8] := b; Vz[ 8] := 0;
        Vx[ 9] := a; Vy[ 9] :=-b; Vz[ 9] := 0;
        Vx[10] :=-a; Vy[10] :=-b; Vz[10] := 0;
        Vx[11] :=-a; Vy[11] := b; Vz[11] := 0;
